namespace DispatchEngine.Core;
public class User { public int Id { get; set; } public string Name { get; set; } = ""; public string Phone { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = ""; }
public class Rider { public int Id { get; set; } public int UserId { get; set; } public bool IsOnline { get; set; } public double CurrentLat { get; set; } public double CurrentLng { get; set; } public DateTime LastSeen { get; set; } public double DistanceKm { get; set; } }
public class Order { public int Id { get; set; } public string Reference { get; set; } = ""; public int CustomerId { get; set; } public int? RiderId { get; set; } public string Status { get; set; } = ""; public double PickupLat { get; set; } public double PickupLng { get; set; } public string PickupAddress { get; set; } = ""; public double DropoffLat { get; set; } public double DropoffLng { get; set; } public string DropoffAddress { get; set; } = ""; public decimal Price { get; set; } public double DistanceKm { get; set; } public string DeliveryOtp { get; set; } = ""; public DateTime CreatedAt { get; set; } }
public class Wallet { public int Id { get; set; } public int UserId { get; set; } public decimal Balance { get; set; } public DateTime UpdatedAt { get; set; } }
public class WalletTransaction { public int Id { get; set; } public int WalletId { get; set; } public string Type { get; set; } = ""; public decimal Amount { get; set; } public string Reference { get; set; } = ""; public string Description { get; set; } = ""; public DateTime CreatedAt { get; set; } }
